insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي بُرْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ الْأَغَرَّ - وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يُحَدِّثُ ابْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمْ - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ، فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ". (م)', 'അബൂബുർദ(റ): നബി(സ)യുടെ അനുചരരിൽപ്പെട്ട അഗർറ്(റ), ഇബ്‌നുഉമർ(റ)വിനെക്കുറിച്ച് പറയുന്നതായി ഞാൻ കേട്ടു. അഗർറ്(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നു. "ഓ ജനങ്ങളേ, നിങ്ങൾ അല്ലാഹുവിലേക്ക് പശ്ചാത്തപിച്ച് മടങ്ങുക. കാരണം, ഞാൻ ദിവസവും നൂറ് പ്രാവശ്യം അല്ലാഹുവിലേക്ക് പശ്ചാത്തപിച്ച് മടങ്ങാറുണ്ട്." (മു)', 'أَبِي بُرْدَةَ', 'അബൂബുർദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 999, 999, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنِ الْحَارِثِ بْنِ سُوَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى عَبْدِ اللَّهِ أَعُودُهُ وَهُوَ مَرِيضٌ، فَحَدَّثَنَا بِحَدِيثَيْنِ: حَدِيثًا عَنْ نَفْسِهِ، وَحَدِيثًا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ الْمُؤْمِنِ مِنْ رَجُلٍ فِي أَرْضِ دَوِّيَّةٍ مَهْلِكَةٍ، مَعَهُ رَاحِلَتُهُ عَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَنَامَ، فَاسْتَيْقَظَ وَقَدْ ذَهَبَتْ، فَطَلَبَهَا حَتَّى أَدْرَكَهُ الْعَطَشُ، ثُمَّ قَالَ: أَرْجِعُ إِلَى مَكَانِيَ الَّذِي كُنْتُ فِيهِ فَأَنَامُ حَتَّى أَمُوتَ، فَوَضَعَ رَأْسَهُ عَلَى سَاعِدِهِ لِيَمُوتَ، فَاسْتَيْقَظَ وَعِنْدَهُ رَاحِلَتُهُ وَعَلَيْهَا زَادُهُ وَطَعَامُهُ وَشَرَابُهُ، فَاللَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ الْعَبْدِ الْمُؤْمِنِ مِنْ هَذَا بِرَاحِلَتِهِ وَزَادِهِ". (م)', 'ഹാരിസുബ്നു സുവൈദ്(റ): അബ്ദുല്ല(റ) അസുഖമായി കിടന്നപ്പോൾ ഞാൻ അവരുടെയടുത്ത്പോയി. അപ്പോൾ രണ്ട് വാർത്തകൾ ഞങ്ങൾക്ക് പറഞ്ഞുതന്നു. ഒന്ന് അദ്ദേഹത്തിന്റെയും മറ്റൊന്ന് റസൂൽ(സ)യുടെയും. അദ്ദേഹം പറഞ്ഞു: ദൈവദൂതർ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മുഅ്മിനായ തന്റെ അടിമയുടെ തൗബ കാരണം അല്ലാഹു ഏറ്റവും കൂടുതൽ സന്തോഷിക്കുന്നവനാകുന്നു. ആരുമില്ലാത്ത ഭയാനകമായ ഒരു മരുഭൂമി. അതിൽ തന്റെ ഭക്ഷണവും വെള്ളവും ചുമക്കുന്ന ഒരു വാഹനവുമായി ഒരാൾ ഉറങ്ങാൻ കിടന്നു. ശേഷം അദ്ദേഹം എഴുന്നേറ്റപ്പോൾ തന്റെ വാഹനം എവിടെയോ പോയിരിക്കുന്നു. അദ്ദേഹം അതിനെ പരതിനടന്ന് ശക്തമായ ദാഹം അനുഭവപ്പെടുകയുണ്ടായി. ദാഹത്തിന്റെ തീവ്രത കാരണം പറഞ്ഞ് പോയി, ഞാൻ ആദ്യമുണ്ടായിരുന്ന സ്ഥലത്ത് പോയി ഉറങ്ങട്ടെ; അങ്ങനെ മരിച്ച് കൊള്ളട്ടെ. അങ്ങനെ കയ്യിൽ തല വെച്ച് മരിക്കാൻ കിടന്നു. പെട്ടെന്നെഴുന്നേറ്റപ്പോൾ പാഥേയവും വെള്ളവും ഭക്ഷണവുമായി തന്റെ വാഹനം തന്റെയടുത്ത് നിൽക്കുന്നു. അന്നേരത്തുള്ള അദ്ദേഹത്തിന്റെ സന്തോഷത്തേക്കാൾ വലിയ സന്തോഷമാണ് ഒരു മുഅ്മിനായ അടിമ അല്ലാഹുവിലേക്ക് തൗബ ചെയ്യുമ്പോൾ അല്ലാഹുവിനുണ്ടാവുക."
(മു)', 'الْحَارِثِ بْنِ سُوَيْدٍ', 'ഹാരിസുബ്നു സുവൈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 999, 1000, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمْ أَتَخَلَّفْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ غَزَاهَا، إِلَّا فِي غَزْوَةِ تَبُوكَ، غَيْرَ أَنِّي كُنْتُ تَخَلَّفْتُ فِي غَزْوَةِ بَدْرٍ وَلَمْ يُعَاتِبْ أَحَدًا تَخَلَّفَ عَنْهَا، إِنَّمَا خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرِيدُ عِيرَ قُرَيْشٍ حَتَّى جَمَعَ اللَّهُ بَيْنَهُمْ وَبَيْنَ عَدُوِّهِمْ عَلَى غَيْرِ مِيعَادٍ، وَلَقَدْ شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ الْعَقَبَةِ حِينَ تَوَاثَقْنَا عَلَى الْإِسْلَامِ، وَمَا أُحِبُّ أَنَّ لِي بِهَا مَشْهَدَ بَدْرٍ وَإِنْ كَانَتْ بَدْرٌ أَذْكَرَ فِي النَّاسِ مِنْهَا، كَانَ مِنْ خَبَرِي أَنِّي لَمْ أَكُنْ قَطُّ أَقْوَى وَلَا أَيْسَرَ حِينَ تَخَلَّفْتُ عَنْهُ، فِي تِلْكَ الْغَزَاةِ، وَاللَّهِ مَا اجْتَمَعَتْ عِنْدِي قَبْلَهُ رَاحِلَتَانِ قَطُّ حَتَّى جَمَعْتُهُمَا فِي تِلْكَ الْغَزْوَةِ، وَلَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرِيدُ غَزْوَةً إِلَّا وَرَّى بِغَيْرِهَا حَتَّى كَانَتْ تِلْكَ الْغَزْوَةُ غَزَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَرٍّ شَدِيدٍ وَاسْتَقْبَلَ سَفَرًا بَعِيدًا وَمَفَازًا وَعَدُوًّا كَثِيرًا، فَجَلَّى لِلْمُسْلِمِينَ أَمْرَهُمْ لِيَتَأَهَّبُوا أُهْبَةَ غَزْوِهِمْ، فَأَخْبَرَهُمْ بِوَجْهِهِ الَّذِي يُرِيدُ وَالْمُسْلِمُونَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَثِيرٌ وَلَا يَجْمَعُهُمْ كِتَابٌ حَافِظٌ، يُرِيدُ الدِّيوَانَ قَالَ كَعْبٌ فَمَا رَجُلٌ يُرِيدُ أَنْ يَتَغَيَّبَ إِلَّا ظَنَّ أَنْ سَيَخْفَى لَهُ مَا لَمْ يَنْزِلْ فِيهِ وَحْيُ اللَّهِ، وَغَزَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِلْكَ الْغَزْوَةَ حِينَ طَابَتِ الثِّمَارُ وَالظِّلَالُ، وَتَجَهَّزَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ مَعَهُ، فَطَفِقْتُ أَغْدُو لِكَيْ أَتَجَهَّزَ مَعَهُمْ فَأَرْجِعُ وَلَمْ أَقْضِ شَيْئًا، فَأَقُولُ فِي نَفْسِي أَنَا قَادِرٌ عَلَيْهِ، فَلَمْ يَزَلْ يَتَمَادَى بِي حَتَّى اشْتَدَّ بِالنَّاسِ الْجِدُّ، فَأَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ مَعَهُ، وَلَمْ أَقْضِ مِنْ جِهَازِي شَيْئًا. فَقُلْتُ أَتَجَهَّزُ بَعْدَهُ بِيَوْمٍ أَوْ يَوْمَيْنِ ثُمَّ أَلْحَقُهُمْ فَغَدَوْتُ بَعْدَ أَنْ فَصَلُوا لِأَتَجَهَّزَ فَرَجَعْتُ وَلَمْ أَقْضِ شَيْئًا، ثُمَّ غَدَوْتُ ثُمَّ رَجَعْتُ وَلَمْ أَقْضِ شَيْئًا، فَلَمْ يَزَلْ بِي حَتَّى أَسْرَعُوا وَتَفَارَطَ الْغَزْوُ وَهَمَمْتُ أَنْ أَرْتَحِلَ فَأُدْرِكَهُمْ وَلَيْتَنِي فَعَلْتُ، فَلَمْ يُقَدَّرْ لِي ذَلِكَ، فَكُنْتُ إِذَا خَرَجْتُ فِي النَّاسِ بَعْدَ خُرُوجِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَطُفْتُ فِيهِمْ أَحْزَنَنِي أَنِّي لَا أَرَى إِلَّا رَجُلًا مَغْمُوصًا عَلَيْهِ النِّفَاقُ أَوْ رَجُلًا مِمَّنْ عَذَرَ اللَّهُ مِنَ الضُّعَفَاءِ، وَلَمْ يَذْكُرْنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَلَغَ تَبُوكَ فَقَالَ وَهُوَ جَالِسٌ فِي الْقَوْمِ بِتَبُوكَ: "مَا فَعَلَ كَعْبٌ؟". فَقَالَ رَجُلٌ مِنْ بَنِي سَلِمَةَ: يَا رَسُولَ اللَّهِ حَبَسَهُ بُرْدَاهُ وَنَظَرُهُ فِي عِطْفَيْهِ، فَقَالَ مُعَاذُ بْنُ جَبَلٍ: بِئْسَ مَا قُلْتَ، وَاللَّهِ يَا رَسُولَ اللَّهِ مَا عَلِمْنَا عَلَيْهِ إِلَّا خَيْرًا فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ كَعْبُ بْنُ مَالِكٍ: فَلَمَّا بَلَغَنِي أَنَّهُ تَوَجَّهَ قَافِلًا حَضَرَنِي هَمِّي وَطَفِقْتُ أَتَذَكَّرُ الْكَذِبَ وَأَقُولُ: بِمَاذَا أَخْرُجُ مِنْ سَخَطِهِ غَدًا؟ وَاسْتَعَنْتُ عَلَى ذَلِكَ بِكُلِّ ذِي رَأْيٍ مِنْ أَهْلِي، فَلَمَّا قِيلَ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَظَلَّ قَادِمًا زَاحَ عَنِّي الْبَاطِلُ، وَعَرَفْتُ أَنِّي لَنْ أَخْرُجَ مِنْهُ أَبَدًا بِشَيْءٍ فِيهِ كَذِبٌ فَأَجْمَعْتُ صِدْقَهُ، وَأَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَادِمًا، وَكَانَ إِذَا قَدِمَ مِنْ سَفَرٍ بَدَأَ بِالْمَسْجِدِ فَيَرْكَعُ فِيهِ رَكْعَتَيْنِ ثُمَّ جَلَسَ لِلنَّاسِ، فَلَمَّا فَعَلَ ذَلِكَ جَاءَهُ الْمُخَلَّفُونَ فَطَفِقُوا يَعْتَذِرُونَ إِلَيْهِ وَيَحْلِفُونَ لَهُ، وَكَانُوا بِضْعَةً وَثَمَانِينَ رَجُلًا، فَقَبِلَ مِنْهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَانِيَتَهُمْ وَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ وَوَكَلَ سَرَائِرَهُمْ إِلَى اللَّهِ تَعَالَى، فَجِئْتُهُ فَلَمَّا سَلَّمْتُ عَلَيْهِ تَبَسَّمَ تَبَسُّمَ الْمُغْضَبِ، ثُمَّ قَالَ: تَعَالَ فَجِئْتُ أَمْشِي حَتَّى جَلَسْتُ بَيْنَ يَدَيْهِ، فَقَالَ لِي: مَا خَلَّفَكَ؟ أَلَمْ تَكُنْ قَدِ ابْتَعْتَ ظَهْرَكَ؟ فَقُلْتُ: بَلَى، وَاللَّهِ يَا رَسُولَ اللَّهِ، وَاللَّهِ لَوْ جَلَسْتُ عِنْدَ غَيْرِكَ مِنْ أَهْلِ الدُّنْيَا لَرَأَيْتُ أَنْ سَأَخْرُجُ مِنْ سَخَطِهِ بِعُذْرٍ، وَلَقَدْ أُعْطِيتُ جَدَلًا، وَلَكِنِّي وَاللَّهِ لَقَدْ عَلِمْتُ لَئِنْ حَدَّثْتُكَ الْيَوْمَ حَدِيثَ كَذِبٍ تَرْضَى بِهِ عَنِّي لَيُوشِكَنَّ اللَّهُ أَنْ يُسْخِطَكَ عَلَيَّ، وَلَئِنْ حَدَّثْتُكَ حَدِيثَ صِدْقٍ تَجِدُ عَلَيَّ فِيهِ إِنِّي لَأَرْجُو فِيهِ عَفْوَ اللَّهِ، لَا وَاللَّهِ مَا كَانَ لِي مِنْ عُذْرٍ، وَاللَّهِ مَا كُنْتُ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا هَذَا فَقَدْ صَدَقَ، فَقُمْ حَتَّى يَقْضِيَ اللَّهُ فِيكَ". فَقُمْتُ وَثَارَ رِجَالٌ مِنْ بَنِي سَلِمَةَ فَاتَّبَعُونِي، فَقَالُوا لِي: وَاللَّهِ مَا عَلِمْنَاكَ كُنْتَ أَذْنَبْتَ ذَنْبًا قَبْلَ هَذَا، وَلَقَدْ عَجَزْتَ أَنْ لَا تَكُونَ اعْتَذَرْتَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا اعْتَذَرَ إِلَيْهِ الْمُتَخَلِّفُونَ، قَدْ كَانَ كَافِيَكَ ذَنْبَكَ اسْتِغْفَارُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَكَ فَوَاللَّهِ مَا زَالُوا يُؤَنِّبُونِي حَتَّى أَرَدْتُ أَنْ أَرْجِعَ فَأُكَذِّبَ نَفْسِي، ثُمَّ قُلْتُ لَهُمْ: هَلْ لَقِيَ هَذَا مَعِي أَحَدٌ؟ قَالُوا: نَعَمْ، رَجُلَانِ قَالَا مِثْلَ مَا قُلْتَ، فَقِيلَ لَهُمَا مِثْلُ مَا قِيلَ لَكَ، فَقُلْتُ: مَنْ هُمَا؟ قَالُوا: مَرَارَةُ بْنُ الرَّبِيعِ الْعَمْرِيُّ، وَهِلَالُ بْنُ أُمَيَّةَ الْوَاقِفِيُّ، فَذَكَرُوا لِي رَجُلَيْنِ صَالِحَيْنِ قَدْ شَهِدَا بَدْرًا، فِيهِمَا أُسْوَةٌ فَمَضَيْتُ حِينَ ذَكَرُوهُمَا لِي. وَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُسْلِمِينَ عَنْ كَلَامِنَا أَيُّهَا الثَّلَاثَةُ مِنْ بَيْنِ مَنْ تَخَلَّفَ عَنْهُ، فَاجْتَنَبَنَا النَّاسُ وَتَغَيَّرُوا لَنَا حَتَّى تَنَكَّرَتْ فِي نَفْسِيَ الْأَرْضُ فَمَا هِيَ الَّتِي أَعْرِفُ، فَلَبِثْنَا عَلَى ذَلِكَ خَمْسِينَ لَيْلَةً، فَأَمَّا صَاحِبَايَ فَاسْتَكَانَا وَقَعَدَا فِي بُيُوتِهِمَا يَبْكِيَانِ، وَأَمَّا أَنَا فَكُنْتُ أَشَبَّ الْقَوْمِ وَأَجْلَدَهُمْ، فَكُنْتُ أَخْرُجُ فَأَشْهَدُ الصَّلَاةَ مَعَ الْمُسْلِمِينَ، وَأَطُوفُ فِي الْأَسْوَاقِ وَلَا يُكَلِّمُنِي أَحَدٌ، وَآتِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُسَلِّمُ عَلَيْهِ وَهُوَ فِي مَجْلِسِهِ بَعْدَ الصَّلَاةِ، فَأَقُولُ فِي نَفْسِي: هَلْ حَرَّكَ شَفَتَيْهِ بِرَدِّ السَّلَامِ عَلَيَّ أَمْ لَا، ثُمَّ أُصَلِّي قَرِيبًا مِنْهُ فَأُسَارِقُهُ النَّظَرَ، فَإِذَا أَقْبَلْتُ عَلَى صَلَاتِي أَقْبَلَ إِلَيَّ وَإِذَا الْتَفَتُّ نَحْوَهُ أَعْرَضَ عَنِّي، حَتَّى إِذَا طَالَ عَلَيَّ ذَلِكَ مِنْ جَفْوَةِ النَّاسِ مَشَيْتُ حَتَّى تَسَوَّرْتُ جِدَارَ حَائِطِ أَبِي قَتَادَةَ، وَهُوَ ابْنُ عَمِّي وَأَحَبُّ النَّاسِ إِلَيَّ، فَسَلَّمْتُ عَلَيْهِ فَوَاللَّهِ مَا رَدَّ عَلَيَّ السَّلَامَ فَقُلْتُ: يَا أَبَا قَتَادَةَ، أَنْشُدُكَ بِاللَّهِ هَلْ تَعْلَمُنِي أُحِبُّ اللَّهَ وَرَسُولَهُ؟ فَسَكَتَ فَعُدْتُ لَهُ فَنَشَدْتُهُ فَسَكَتَ فَعُدْتُ لَهُ فَنَشَدْتُهُ، فَقَالَ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، فَفَاضَتْ عَيْنَايَ وَتَوَلَّيْتُ حَتَّى تَسَوَّرْتُ الْجِدَارَ، قَالَ: فَبَيْنَا أَنَا أَمْشِي بِسُوقِ الْمَدِينَةِ إِذَا نَبَطِيٌّ مِنْ أَنْبَاطِ أَهْلِ الشَّأْمِ مِمَّنْ قَدِمَ بِالطَّعَامِ يَبِيعُهُ بِالْمَدِينَةِ يَقُولُ مَنْ يَدُلُّ عَلَى كَعْبِ بْنِ مَالِكٍ، فَطَفِقَ النَّاسُ يُشِيرُونَ لَهُ، حَتَّى إِذَا جَاءَنِي دَفَعَ إِلَيَّ كِتَابًا مِنْ مَلِكِ غَسَّانَ، فَإِذَا فِيهِ: أَمَّا بَعْدُ: فَإِنَّهُ قَدْ بَلَغَنِي أَنَّ صَاحِبَكَ قَدْ جَفَاكَ، وَلَمْ يَجْعَلْكَ اللَّهُ بِدَارِ هَوَانٍ وَلَا مَضْيَعَةٍ فَالْحَقْ بِنَا نُوَاسِكَ، فَقُلْتُ لَمَّا قَرَأْتُهَا: وَهَذَا أَيْضًا مِنَ الْبَلَاءِ، فَتَيَمَّمْتُ بِهَا التَّنُّورَ فَسَجَرْتُهُ بِهَا حَتَّى إِذَا مَضَتْ أَرْبَعُونَ لَيْلَةً مِنَ الْخَمْسِينَ إِذَا رَسُولُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِينِي فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ، فَقُلْتُ: أُطَلِّقُهَا أَمْ مَاذَا أَفْعَلُ؟ قَالَ: لَا، بَلِ اعْتَزِلْهَا وَلَا تَقْرَبْهَا، وَأَرْسَلَ إِلَى صَاحِبَيَّ مِثْلَ ذَلِكَ، فَقُلْتُ لِامْرَأَتِي: الْحَقِي بِأَهْلِكِ فَتَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ فِي هَذَا الْأَمْرِ، قَالَ كَعْبٌ: فَجَاءَتِ امْرَأَةُ هِلَالِ بْنِ أُمَيَّةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ إِنَّ هِلَالَ بْنَ أُمَيَّةَ شَيْخٌ ضَائِعٌ لَيْسَ لَهُ خَادِمٌ، فَهَلْ تَكْرَهُ أَنْ أَخْدُمَهُ، قَالَ: لَا، وَلَكِنْ لَا يَقْرَبْكِ، قَالَتْ: إِنَّهُ وَاللَّهِ مَا بِهِ حَرَكَةٌ إِلَى شَيْءٍ وَاللَّهِ مَا زَالَ يَبْكِي مُنْذُ كَانَ مِنْ أَمْرِهِ مَا كَانَ إِلَى يَوْمِهِ هَذَا، فَقَالَ لِي بَعْضُ أَهْلِي: لَوِ اسْتَأْذَنْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي امْرَأَتِكَ، كَمَا أَذِنَ لِامْرَأَةِ هِلَالِ بْنِ أُمَيَّةَ أَنْ تَخْدُمَهُ فَقُلْتُ: وَاللَّهِ لَا أَسْتَأْذِنُ فِيهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا يُدْرِينِي مَا يَقُولُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَأْذَنْتُهُ فِيهَا، وَأَنَا رَجُلٌ شَابٌّ، فَلَبِثْتُ بَعْدَ ذَلِكَ عَشْرَ لَيَالٍ، حَتَّى كَمَلَتْ لَنَا خَمْسُونَ لَيْلَةً مِنْ حِينَ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ كَلَامِنَا، فَلَمَّا صَلَّيْتُ صَلَاةَ الْفَجْرِ صُبْحَ خَمْسِينَ لَيْلَةً، وَأَنَا عَلَى ظَهْرِ بَيْتٍ مِنْ بُيُوتِنَا، فَبَيْنَا أَنَا جَالِسٌ عَلَى الْحَالِ الَّتِي ذَكَرَ اللَّهُ قَدْ ضَاقَتْ عَلَيَّ نَفْسِي وَضَاقَتْ عَلَيَّ الْأَرْضُ بِمَا رَحُبَتْ، سَمِعْتُ صَوْتَ صَارِخٍ أَوْفَى عَلَى جَبَلِ سَلْعٍ بِأَعْلَى صَوْتِهِ يَا كَعْبُ بْنَ مَالِكٍ أَبْشِرْ: قَالَ: فَخَرَرْتُ سَاجِدًا، وَعَرَفْتُ أَنْ قَدْ جَاءَ فَرَجٌ وَآذَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَوْبَةِ اللَّهِ عَلَيْنَا حِينَ صَلَّى صَلَاةَ الْفَجْرِ، فَذَهَبَ النَّاسُ يُبَشِّرُونَنَا، وَذَهَبَ قِبَلَ صَاحِبَيَّ مُبَشِّرُونَ، وَرَكَضَ إِلَيَّ رَجُلٌ فَرَسًا، وَسَعَى سَاعٍ مِنْ أَسْلَمَ فَأَوْفَى عَلَى الْجَبَلِ، وَكَانَ الصَّوْتُ أَسْرَعَ مِنَ الْفَرَسِ، فَلَمَّا جَاءَنِي الَّذِي سَمِعْتُ صَوْتَهُ يُبَشِّرُنِي نَزَعْتُ لَهُ ثَوْبَيَّ فَكَسَوْتُهُ إِيَّاهُمَا بِبُشْرَاهُ، وَاللَّهِ مَا أَمْلِكُ غَيْرَهُمَا يَوْمَئِذٍ وَاسْتَعَرْتُ ثَوْبَيْنِ فَلَبِسْتُهُمَا وَانْطَلَقْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَتَلَقَّانِي النَّاسُ فَوْجًا فَوْجًا يُهَنُّونِي بِالتَّوْبَةِ، يَقُولُونَ لِتَهْنِكَ تَوْبَةُ اللَّهِ عَلَيْكَ، قَالَ كَعْبٌ: حَتَّى دَخَلْتُ الْمَسْجِدَ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ حَوْلَهُ النَّاسُ، فَقَامَ إِلَيَّ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ يُهَرْوِلُ حَتَّى صَافَحَنِي وَهَنَّانِي، وَاللَّهِ مَا قَامَ إِلَيَّ رَجُلٌ مِنَ الْمُهَاجِرِينَ غَيْرُهُ، وَلَا أَنْسَاهَا لِطَلْحَةَ، قَالَ كَعْبٌ: فَلَمَّا سَلَّمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَبْرُقُ وَجْهُهُ مِنَ السُّرُورِ: "أَبْشِرْ بِخَيْرِ يَوْمٍ مَرَّ عَلَيْكَ مُنْذُ وَلَدَتْكَ أُمُّكَ". قَالَ: قُلْتُ أَمِنْ عِنْدِكَ يَا رَسُولَ اللَّهِ أَمْ مِنْ عِنْدِ اللَّهِ؟ قَالَ: لَا بَلْ مِنْ عِنْدِ اللَّهِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سُرَّ اسْتَنَارَ وَجْهُهُ حَتَّى كَأَنَّهُ قِطْعَةُ قَمَرٍ، وَكُنَّا نَعْرِفُ ذَلِكَ مِنْهُ، فَلَمَّا جَلَسْتُ بَيْنَ يَدَيْهِ قُلْتُ، يَا رَسُولَ اللَّهِ إِنَّ مِنْ تَوْبَتِي أَنْ أَنْخَلِعَ مِنْ مَالِي صَدَقَةً إِلَى اللَّهِ، وَإِلَى رَسُولِ اللَّهِ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمْسِكْ عَلَيْكَ بَعْضَ مَالِكَ فَهُوَ خَيْرٌ لَكَ". قُلْتُ: فَإِنِّي أُمْسِكُ سَهْمِيَ الَّذِي بِخَيْبَرَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ إِنَّمَا نَجَّانِي بِالصِّدْقِ وَإِنَّ مِنْ تَوْبَتِي أَنْ لَا أُحَدِّثَ إِلَّا صِدْقًا مَا بَقِيتُ، فَوَاللَّهِ مَا أَعْلَمُ أَحَدًا مِنَ الْمُسْلِمِينَ أَبْلَاهُ اللَّهُ فِي صِدْقِ الْحَدِيثِ مُنْذُ ذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحْسَنَ مِمَّا أَبْلَانِي، مَا تَعَمَّدْتُ مُنْذُ ذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى يَوْمِي هَذَا كَذِبًا، وَإِنِّي لَأَرْجُو أَنْ يَحْفَظَنِي اللَّهُ فِيمَا بَقِيتُ. وَأَنْزَلَ اللَّهُ عَلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {لَقَدْ تَابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالأَنْصَارِ} إِلَى قَوْلِهِ {وَكُونُوا مَعَ الصَّادِقِينَ} فَوَاللَّهِ مَا أَنْعَمَ اللَّهُ عَلَيَّ مِنْ نِعْمَةٍ قَطُّ، بَعْدَ أَنْ هَدَانِي لِلإِسْلَامِ أَعْظَمَ فِي نَفْسِي مِنْ صِدْقِي لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا أَكُونَ كَذَبْتُهُ فَأَهْلِكَ، كَمَا هَلَكَ الَّذِينَ كَذَبُوا، فَإِنَّ اللَّهَ قَالَ لِلَّذِينَ كَذَبُوا حِينَ أَنْزَلَ الْوَحْيَ، شَرَّ مَا قَالَ لِأَحَدٍ، فَقَالَ اللَّهُ عَزَّ وَجَلَّ: {سَيَحْلِفُونَ بِاللَّهِ لَكُمْ إِذَا انْقَلَبْتُمْ...} إِلَى قَوْلِهِ {فَإِنَّ اللَّهَ لَا يَرْضَى عَنِ الْقَوْمِ الْفَاسِقِينَ} قَالَ كَعْبٌ: وَكُنَّا تَخَلَّفْنَا أَيُّهَا الثَّلَاثَةُ عَنْ أَمْرِ أُولَئِكَ الَّذِينَ قَبِلَ مِنْهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ حَلَفُوا لَهُ فَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ وَأَرْجَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْرَنَا حَتَّى قَضَى اللَّهُ فِيهِ فَبِذَلِكَ قَالَ اللَّهُ عَزَّ وَجَلَّ: {وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا} وَلَيْسَ الَّذِي ذَكَرَ اللَّهُ مِمَّا خُلِّفْنَا عَنِ الْغَزْوِ، إِنَّمَا هُوَ تَخْلِيفُهُ إِيَّانَا، وَإِرْجَاؤُهُ أَمْرَنَا عَمَّنْ حَلَفَ لَهُ وَاعْتَذَرَ إِلَيْهِ فَقَبِلَ مِنْهُ. (م)', 'കഅ്ബുബ്നു മാലിക്(റ): തിരുമേനി(സ) പങ്കെടുത്ത യുദ്ധങ്ങളിൽ, തബൂക് ഒഴികെ മറ്റൊന്നിലും ഞാൻ പങ്കെടുക്കാതിരുന്നിട്ടില്ല. ബദർയുദ്ധത്തിൽ ഞാൻ പങ്കെടുത്തിരുന്നില്ലെങ്കിലും അതിൽ പങ്കെടുക്കാതിരുന്നത് കൊണ്ട് അല്ലാഹു ആരെയും ആക്ഷേപിച്ചിട്ടില്ല. അന്ന് തിരുമേനി(സ) ഖുറൈശികളുടെ കച്ചവടസംഘത്തെ ലക്ഷ്യമാക്കി പുറപ്പെട്ടതായിരുന്നു. അങ്ങനെ മുസ്‌ലിംകളെയും ശത്രുക്കളെയും അവിചാരിതമായി അല്ലാഹു കൂട്ടിമുട്ടിച്ചു. അഖബയിൽ വെച്ച് ഇസ്‌ലാമിന്റെ പേരിൽ കരാർ ചെയ്ത രാത്രി തിരുമേനി(സ)യുടെ കൂടെ ഞാൻ സന്നിഹിതനായിരുന്നു. ജനങ്ങളുടെ അടുക്കൽ ബദർയുദ്ധത്തിനായിരുന്നു അഖബാ കരാറിനേക്കാൾ കൂടുതൽ പ്രസിദ്ധിയെങ്കിലും; അഖബസംഭവത്തിൽ പങ്കെടുക്കാൻ അവസരം ലഭിച്ചതാണ് ബദർ യുദ്ധത്തിൽ പങ്കെടുക്കാൻ അവസരം ലഭിക്കുന്നതിനേക്കാൾ എനിക്ക് പ്രിയങ്കരം. തബൂക്‌യുദ്ധത്തിൽ പങ്കെടുക്കാതെ വിട്ടുനിന്ന കാലത്തേതുപോലെ ആരോഗ്യവും സമ്പത്തും അതിന്റെ മുമ്പൊരിക്കലും എനിക്കുണ്ടായിരുന്നില്ല. അല്ലാഹുവാണ്, അതിന് മുമ്പ് ഒരിക്കലും രണ്ട് വാഹനങ്ങൾ എനിക്കുണ്ടായിട്ടില്ല. ആ യുദ്ധ ഘട്ടത്തിൽ എനിക്ക് രണ്ട് വാഹനങ്ങൾ ഉണ്ടായിരുന്നു. ഒരു യുദ്ധത്തിന് പുറപ്പെടാനുദ്ദേശിച്ചാൽ വ്യംഗ്യമായി മറ്റൊന്നു പറയുകയായിരുന്നു തിരുമേനി(സ)യുടെ പതിവ്. ഈ യുദ്ധ ഘട്ടത്തിലാകട്ടെ അതികഠിനമായ ചൂടിൽ, മരുഭൂമിയിലൂടെ വിദൂര യാത്രക്കു ശേഷം വമ്പിച്ച ശത്രു സമൂഹത്തെ നേരിട്ടു കൊണ്ടാണ് തിരുമേനി(സ)ക്ക് യുദ്ധം ചെയ്യേണ്ടി വന്നത്. മുസ്‌ലിംകൾക്ക് അവരുടെ യുദ്ധത്തിന് വേണ്ട സന്നാഹങ്ങളൊരുക്കുവാനായി എല്ലാ കാര്യങ്ങളും തിരുമേനി വ്യക്തമാക്കിക്കൊടുത്തു. ആദ്യമേ തന്നെ തന്റെ ലക്ഷ്യം തിരുമേനി(സ) അവരെ അറിയിച്ചു. തിരുമേനി(സ)യുടെ കൂടെ യുദ്ധത്തിൽ പങ്കെടുക്കാൻ ധാരാളം മുസ്‌ലിംകളുണ്ടായിരുന്നു. അവരുടെ പേര് മുഴുവനും ഒരു പട്ടാള രജിസ്റ്ററിൽ രേഖപ്പെടുത്തിയിരുന്നില്ല. യുദ്ധത്തിൽ പങ്കെടുക്കാതെ ഒഴിഞ്ഞു നിൽക്കാൻ ഉദ്ദേശിക്കുന്ന ചില ആളുകൾ അല്ലാഹുവിങ്കൽ നിന്ന് വഹ്യ് ലഭിക്കുംവരേക്കും തിരുമേനി(സ)ക്കും അവരെക്കുറിച്ച് അറിയാൻ കഴിയില്ലെന്ന് ധരിച്ചു. വൃക്ഷങ്ങൾ തളിർത്ത് നിഴലുകൾക്ക് കനം കൂടുകയും ഫലങ്ങൾ മൂപ്പെത്തുകയും ചെയ്ത അവസരത്തിലാണ് തിരുമേനി ആ യുദ്ധത്തിന് പോയത്. തിരുമേനി(സ)യും മുസ്‌ലിംകളും യുദ്ധ സന്നാഹങ്ങൾ ഒരുക്കി. അവരോടൊപ്പം സന്നാഹങ്ങളൊരുക്കാൻ രാവിലെ ഞാൻ പുറപ്പെടും, വൈകുന്നേരം മടങ്ങുമ്പോൾ ഒരുക്കങ്ങളൊന്നും ഞാൻ ചെയ്തിട്ടുണ്ടായിരിക്കുകയുമില്ല. ഞാൻ മനസ്സിൽ പറയും: എനിക്കത് എപ്പോൾ വേണമെങ്കിലും ചെയ്യാൻ കഴിയും. അങ്ങനെ വിചാരിച്ച് ദിവസങ്ങൾ പിന്നിട്ടു. യുദ്ധത്തിന് പുറപ്പെടാനുള്ള ഒരുക്കം വളരെ ക്ലേശിച്ച് ജനങ്ങൾ നിർവ്വഹിച്ചു. ഒരു ദിവസം രാവിലെ തിരുമേനി(സ)യും മുസ്‌ലിംകളും യുദ്ധത്തിന് പുറപ്പെട്ടു. ഞാനാകട്ടെ ഒരു ഒരുക്കവും ചെയ്തിട്ടുമില്ല. ഒന്നോ രണ്ടോ ദിവസത്തിനകം ഒരുക്കങ്ങൾ പൂർത്തിയാക്കി അവരോടൊപ്പം ചെന്നു ചേരാം എന്നായി എന്റെ സങ്കൽപ്പം. അവർ പോയ ശേഷം ദിവസവും രാവിലെ ഞാൻ യുദ്ധത്തിനൊരുങ്ങാൻ ഉദ്ദേശിച്ചു പോകും. അന്നും തിരിച്ചു പോരും. ഒന്നും ചെയ്തിട്ടുണ്ടായിരിക്കുകയുമില്ല. ഇതായി എന്റെ പതിവ്. ഒടുവിൽ മറ്റുള്ളവർ ധൃതിപ്പെട്ട് മുന്നോട്ട് പോകുകയും യുദ്ധം എന്റെ പിടുത്തത്തിൽനിന്ന് വിട്ടുപോവുകയും ചെയ്തുവെന്ന് കണ്ടപ്പോൾ വേഗം യാത്ര ചെയ്തു അവരോടൊപ്പം എത്താമെന്ന് പിന്നെയും ഞാനുദ്ദേശിച്ചു. അങ്ങനെ ചെയ്തെങ്കിൽ എത്ര നന്നായിരുന്നേനെ. പക്ഷെ എനിക്കതു വിധിക്കപ്പെട്ടിട്ടുണ്ടായിരുന്നില്ല.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَانَ فِيمَنْ كَانَ قَبْلَكُمْ رَجُلٌ قَتَلَ تِسْعَةً وَتِسْعِينَ نَفْسًا، فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ، فَدُلَّ عَلَى رَاهِبٍ، فَأَتَاهُ فَقَالَ: إِنَّهُ قَتَلَ تِسْعَةً وَتِسْعِينَ نَفْسًا، فَهَلْ لَهُ مِنْ تَوْبَةٍ؟ فَقَالَ: لَا، فَقَتَلَهُ، فَكَمَّلَ بِهِ مِائَةً، ثُمَّ سَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ، فَدُلَّ عَلَى رَجُلٍ عَالِمٍ، فَقَالَ: إِنَّهُ قَتَلَ مِائَةَ نَفْسٍ، فَهَلْ لَهُ مِنْ تَوْبَةٍ؟ فَقَالَ: نَعَمْ، وَمَنْ يَحُولُ بَيْنَهُ وَبَيْنَ التَّوْبَةِ؟ انْطَلِقْ إِلَى أَرْضِ كَذَا وَكَذَا، فَإِنَّ بِهَا أُنَاسًا يَعْبُدُونَ اللَّهَ عَزَّ وَجَلَّ، فَاعْبُدِ اللَّهَ مَعَهُمْ، وَلَا تَرْجِعْ إِلَى أَرْضِكَ فَإِنَّهَا أَرْضُ سَوْءٍ. فَانْطَلَقَ حَتَّى إِذَا نَصَفَ الطَّرِيقَ أَتَاهُ الْمَوْتُ، فَاخْتَصَمَتْ فِيهِ مَلَائِكَةُ الرَّحْمَةِ وَمَلَائِكَةُ الْعَذَابِ، فَقَالَتْ مَلَائِكَةُ الرَّحْمَةِ: جَاءَ تَائِبًا مُقْبِلًا بِقَلْبِهِ إِلَى اللَّهِ عَزَّ وَجَلَّ. وَقَالَتْ مَلَائِكَةُ الْعَذَابِ: إِنَّهُ لَمْ يَعْمَلْ خَيْرًا قَطُّ. فَأَتَاهُمْ مَلَكٌ فِي صُورَةِ آدَمِيٍّ، فَجَعَلُوهُ بَيْنَهُمْ، فَقَالَ: قِيسُوا مَا بَيْنَ الْأَرْضَيْنِ، فَإِلَى أَيَّتِهِمَا كَانَ أَدْنَى فَهُوَ لَهُ، فَقَاسُوا فَوَجَدُوهُ أَدْنَى إِلَى الْأَرْضِ الَّتِي أَرَادَ. فَقَبَضَتْهُ مَلَائِكَةُ الرَّحْمَةِ". قَالَ قَتَادَةُ: فَقَالَ الْحَسَنُ: ذُكِرَ لَنَا أَنَّهُ لَمَّا أَتَاهُ الْمَوْتُ نَاءَ بِصَدْرِهِ. (م)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: നിങ്ങളുടെ മുമ്പുള്ള സമൂഹത്തിൽ തൊണ്ണൂറ്റി ഒൻപത് പേരെ കൊന്ന ഒരു വ്യക്തിയുണ്ടായിരുന്നു. ഭൂമിയിലെ ഏറ്റവും വലിയ പണ്ഡിതനെക്കുറിച്ച് അദ്ദേഹം ചോദിച്ചപ്പോൾ ഒരു പുരോഹിതനെക്കുറിച്ച് പറഞ്ഞു കൊടുത്തു. അദ്ദേഹത്തിന്റെയടുത്ത് പോയി ചോദിച്ചു: തൊണ്ണൂറ്റി ഒൻപത് ആളുകളെ കൊന്നവന് തൗബയുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല, അദ്ദേഹം ആ പുരോഹിതനെയും കൊന്ന് 100 തികച്ചു. ശേഷം ഏറ്റവും അറിവുള്ള ആളെ അദ്ദേഹം അന്വേഷിക്കുകയും ഒരു വലിയ ആലിമിനെക്കുറിച്ച് അദ്ദേഹത്തിന് വിവരം നൽകപ്പെടുകയും ചെയ്തു. അദ്ദേഹത്തോട് ചോദിച്ചു: നൂറാളുകളെ കൊന്നവന് തൗബയുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: ''അതെ, അവന്റെയും തൗബയുടെയും ഇടയിൽ ആരാണ് മറയിടാനുള്ളത്? നീ ഇന്ന സ്ഥലത്ത് പോകുക, അവിടെ ശ്രേഷ്ഠനും അത്യുന്നതനുമായ അല്ലാഹുവിനെ ആരാധിക്കുന്ന ചിലയാളുകളുണ്ട്. അവരോട് കൂടെ നീ ആരാധന ചെയ്യുക. നിന്റെ സ്ഥലത്തേക്ക് നീ മടങ്ങരുത്. കാരണമതി മോശമായ സ്ഥലമാകുന്നു.'' അങ്ങനെ അദ്ദേഹം പോയി. വഴിയുടെ മധ്യത്തിൽ വെച്ച് അദ്ദേഹം മരണപ്പെട്ടു. അവന്റെ വിഷയത്തിൽ റഹ്‌മതിന്റെയും ശിക്ഷയുടെയും മലക്കുകൾ തമ്മിൽ തർക്കിച്ചു. റഹ്‌മതിന്റെ മലക്കുകൾ പറഞ്ഞു: അദ്ദേഹം തന്റെ ഹൃദയം കൊണ്ട് അല്ലാഹുവിലേക്ക് പശ്ചാതപിച്ച് മടങ്ങിയാണ് വരുന്നത്. ശിക്ഷയുടെ മലക്കുകൾ പറഞ്ഞു: അദ്ദേഹം ഒരു നന്മയും ചെയ്തിട്ടില്ല. അപ്പോൾ അവരിലേക്ക് മനുഷ്യ രൂപത്തിൽ ഒരു മലക്ക് വരികയും അവർ അദ്ദേഹത്തെ മധ്യസ്ഥനാക്കുകയും ചെയ്തു. എന്നിട്ട് ആ മലക്ക് പറഞ്ഞു: രണ്ട് സ്ഥലങ്ങളും നിങ്ങൾ അളക്കുക. ഏത് സ്ഥലത്തേക്കാണ് അദ്ദേഹം ഏറ്റവും അടുത്ത് കിടക്കുന്നതെങ്കിൽ അവൻ അതിന്റെയാളാണ്. അങ്ങനെ അവർ അളക്കുകയും അവൻ പോകുന്ന നാട്ടിലേക്ക് അടുത്തതായി കാണുകയും ചെയ്തു. അപ്പോൾ റഹ്മതിന്റെ മലക്കുകൾ എടുത്ത് കൊണ്ടുപോയി. ഖതാദ(റ) പറഞ്ഞു: ഹസൻ(റ) പറയുന്നു: ആ മനുഷ്യന് മരണം ആഗതമായപ്പോൾ തന്റെ നെഞ്ച് കൊണ്ട് മുന്നോട്ട് ഞരങ്ങി എന്നത് ഞങ്ങളോട് പറയപ്പെട്ടു. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1008, 1008, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللَّهُ عَلَيْهِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "സൂര്യൻ പടിഞ്ഞാറുനിന്ന് ഉദിക്കുംമുമ്പ് ആരെങ്കിലും തൗബ ചെയ്താൽ അല്ലാഹു അത് സ്വീകരിക്കുന്നതാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1009, 1009, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ، حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا". (م)', 'അബൂമുസ(റ): നബി(സ) പറയുന്നു: "സൂര്യൻ പടിഞ്ഞാറുനിന്ന് ഉദിക്കുന്നതുവരെ പകലിൽ ചെയ്ത തെറ്റുകൾക്ക് തൗബ സ്വീകരിക്കാൻ രാത്രിയും രാത്രി ചെയ്തവയുടെ തൗബ സ്വീകരിക്കാൻ പകലും അല്ലാഹു തന്റെ കൈകൾ അടിമകൾക്ക് നേരെ നീട്ടും." (മു)', 'أَبِي مُوسَى', 'അബൂമുസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1009, 1009, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ لَوْ لَمْ تُذْنِبُوا لَذَهَبَ اللَّهُ بِكُمْ وَلَجَاءَ بِقَوْمٍ يُذْنِبُونَ فَيَسْتَغْفِرُونَ اللَّهَ فَيَغْفِرُ لَهُمْ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം. നിങ്ങൾ പാപങ്ങൾ ചെയ്യുന്നില്ലായിരുന്നെങ്കിൽ അല്ലാഹു നിങ്ങളെ കൊണ്ടുപോയി, പകരം പാപം ചെയ്യുകയും ശേഷം അല്ലാഹുവിനോട് പൊറുക്കലിനെ തേടുകയും എന്നിട്ട് അല്ലാഹു അവർക്ക് പൊറുത്ത് കൊടുക്കുകയും ചെയ്യുന്ന ഒരു സമുദായത്തെ കൊണ്ടുവരുമായിരുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1009, 1009, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابِهِ عَلَى نَفْسِهِ، فَهْوَ مَوْضُوعٌ عِنْدَهُ: إِنَّ رَحْمَتِي تَغْلِبُ غَضَبِي". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു സൃഷ്ടിപ്പ് പൂർത്തിയാക്കിയപ്പോൾ തന്റെ കിതാബിൽ സ്വന്തമായി ഇപ്രകാരം എഴുതി വെച്ചു. -അത് അവന്റെയടുത്ത് വെക്കപ്പെട്ടതാണ്-: നിശ്ചയം എന്റെ കരുണ എന്റെ ദേഷ്യത്തെ മറികടക്കുന്നതാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1009, 1009, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ لِلَّهِ مِائَةَ رَحْمَةٍ، أَنْزَلَ مِنْهَا رَحْمَةً وَاحِدَةً بَيْنَ الْجِنِّ وَالْإِنْسِ وَالْبَهَائِمِ وَالْهَوَامِّ، فَبِهَا يَتَعَاطَفُونَ، وَبِهَا يَتَرَاحَمُونَ، وَبِهَا تَعْطِفُ الْوَحْشُ عَلَى وَلَدِهَا. وَأَخَّرَ اللَّهُ تِسْعًا وَتِسْعِينَ رَحْمَةً، يَرْحَمُ بِهَا عِبَادَهُ يَوْمَ الْقِيَامَةِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന് നൂറ് കരുണയുണ്ട്. അവയിൽ നിന്ന് ഒരൊറ്റ റഹ്മത് മാത്രമാണ് അല്ലാഹു ജിന്നുകൾക്കും, മനുഷ്യർക്കും മൃഗങ്ങൾക്കും പ്രാണികൾക്കും ഇടയിൽ ഇറക്കിയത്. അത് കൊണ്ടാണ് അവർ പരസ്പരം കൃപ കാണിക്കുന്നതും കരുണ ചെയ്യുന്നതും. അത് കൊണ്ടാണ് കാട്ടു മൃഗങ്ങൾ അവയുടെ കുട്ടികളോട് കൃപ കാണിക്കുന്നതും. ബാക്കി 99 റഹ്മതും അല്ലാഹു പിന്തിപ്പിച്ചിരിക്കുന്നു. അന്ത്യനാളിൽ അവൻ അത് കൊണ്ട് തന്റെ അടിമകളോട് കരുണ കാണിക്കും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1009, 1010, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ مِنَ الْعُقُوبَةِ مَا طَمِعَ بِجَنَّتِهِ أَحَدٌ، وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنَ الرَّحْمَةِ مَا قَنِطَ مِنْ جَنَّتِهِ أَحَدٌ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "അല്ലാഹുവിന്റെയടുത്തുള്ള ശിക്ഷയെക്കുറിച്ച് ഏതെങ്കിലും സത്യവിശ്വാസി അറിയുമായിരുന്നെങ്കിൽ ആരും അവന്റെ സ്വർഗ്ഗം ആഗ്രഹിക്കുകയില്ലായിരുന്നു. ഒരു കാഫിർ അല്ലാഹുവിന്റെ റഹ്മതിനെക്കുറിച്ച് അറിയുകയായിരുന്നുവെങ്കിൽ ആരും അവന്റെ സ്വർഗ്ഗത്തിൽ നിന്ന് ആശമുറിയില്ലായിരുന്നു. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1010, 1010, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: قَدِمَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْيٌ، فَإِذَا امْرَأَةٌ مِنَ السَّبْي تَبْتَغِي، إِذَا وَجَدَتْ صَبِيًّا فِي السَّبْي أَخَذَتْهُ فَأَلْصَقَتْهُ بِبَطْنِهَا وَأَرْضَعَتْهُ، فَقَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَتَرَوْنَ هَذِهِ الْمَرْأَةَ طَارِحَةً وَلَدَهَا فِي النَّارِ". قُلْنَا: لَا وَاللَّهِ، وَهِيَ تَقْدِرُ عَلَى أَنْ لَا تَطْرَحَهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَلَّهُ أَرْحَمُ بِعِبَادِهِ مِنْ هَذِهِ بِوَلَدِهَا". (م)', 'ഉമറുബ്നുൽ ഖത്വാബ്(റ): റസൂൽ(സ)യുടെ അടുത്തേക്ക് കുറച്ച് ബന്ധികളെ കൊണ്ടുവന്നു. അവയിൽ ഒരു സ്ത്രീ തന്റെ കുട്ടിയെ അന്വേഷിച്ചുകൊണ്ടിരുന്നു. അങ്ങനെ തന്റെ കുട്ടിയെ കിട്ടിയപ്പോൾ അതിനെ മാറോട് ചേർത്ത് പിടിച്ച് മുലയൂട്ടാൻ തുടങ്ങി. അപ്പോൾ നബി(സ) ഞങ്ങളോട് ചോദിച്ചു. ഈ സ്ത്രീ തന്റെ കുട്ടിയെ തീയിലിടുമെന്ന് നിങ്ങൾ വിചാരിക്കുന്നുണ്ടോ. ഞങ്ങൾ പറഞ്ഞു: ഇല്ല, അല്ലാഹുവാണ് സത്യം, അവൾ കുട്ടിയെ അതിൽ ഇടാതിരിക്കാൻ ശ്രമിക്കും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഈ സ്ത്രീ തന്റെ കുട്ടിയോട് കാണിക്കുന്നതിനേക്കാൾ അല്ലാഹു തന്റെ അടിമകളോട് കരുണ ചെയ്യുന്നവനാകുന്നു." (മു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്വാബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1010, 1010, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا كَانَتْ تَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَدِّدُوا وَقَارِبُوا، وَأَبْشِرُوا، فَإِنَّهُ لَنْ يُدْخِلَ الْجَنَّةَ أَحَدًا عَمَلُهُ". قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: "وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِرَحْمَةٍ. وَاعْلَمُوا أَنَّ أَحَبَّ الْعَمَلِ إِلَى اللَّهِ أَدْوَمُهُ وَإِنْ قَلَّ". (م)', 'ആഇശ(റ): മഹതി പറയാറുണ്ടായിരുന്നു: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ശരിയിലേക്ക് തിരിച്ചു വിടുക. നിങ്ങൾ അല്ലാഹുവിലേക്ക് അടുക്കുക. നിങ്ങൾ സന്തോഷവാന്മാരായിരിക്കുക. കാരണം ആരുടെയും പ്രവർത്തനങ്ങൾ അവരെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയില്ല." അവർ ചോദിച്ചു: തിരുദൂതരെ, അങ്ങയേയും പ്രവേശിപ്പിക്കുകയില്ലേ? അവിടുന്ന് പറഞ്ഞു: "എന്നെയും പ്രവേശിപ്പിക്കുകയില്ല. അല്ലാഹു അവന്റെ റഹ്മത് കൊണ്ട് എന്നെ പൊതിഞ്ഞാൽ ഒഴികെ." നിങ്ങൾ അറിയുക, അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട കർമ്മങ്ങൾ പതിവാക്കപ്പെടുന്നവയാണ്. അത് എത്ര കുറവാണെങ്കിലും." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1010, 1011, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَبْدِ اللَّهِ بْنِ قَيْسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَحَدٌ أَصْبَرَ عَلَى أَذًى يَسْمَعُهُ مِنَ اللَّهِ تَعَالَى، إِنَّهُمْ يَجْعَلُونَ لَهُ نِدًّا وَيَجْعَلُونَ لَهُ وَلَدًا، وَهُوَ مَعَ ذَلِكَ يَرْزُقُهُمْ وَيُعَافِيهِمْ وَيُعْطِيهِمْ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഖൈസ്(റ): റസൂൽ(സ) പറയുന്നു. "അനിഷ്ടകരമായ കാര്യങ്ങൾ കേൾക്കുമ്പോൾ അല്ലാഹുവിനേക്കാൾ ക്ഷമിക്കുന്നവൻ ആരുമില്ല. നിശ്ചയം അവർ (ജനങ്ങൾ) അല്ലാഹുവിന് പങ്കാളിയും കുട്ടികളുമുണ്ടെന്ന് പറയുന്നു. അവർ ഈ അവസ്ഥയിലാകുമ്പോൾ തന്നെ അല്ലാഹു അവർക്ക് ഭക്ഷണവും ആരോഗ്യവും കോരിച്ചൊരിഞ്ഞ് കൊടുക്കുന്നു." (മു)', 'عَبْدِ اللَّهِ بْنِ قَيْسٍ', 'അബ്ദുല്ലാഹിബ്നു ഖൈസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1011, 1011, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ أَحَدٌ أَحَبَّ إِلَيْهِ الْمَدْحُ مِنَ اللَّهِ عَزَّ وَجَلَّ، مِنْ أَجْلِ ذَلِكَ مَدَحَ نَفْسَهُ. وَلَيْسَ أَحَدٌ أَغْيَرَ مِنَ اللَّهِ، مِنْ أَجْلِ ذَلِكَ حَرَّمَ الْفَوَاحِشَ، وَلَيْسَ أَحَدٌ أَحَبَّ إِلَيْهِ الْعُذْرُ مِنَ اللَّهِ، مِنْ أَجْلِ ذَلِكَ أَنْزَلَ الْكِتَابَ وَأَرْسَلَ الرُّسُلَ". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറയുന്നു: "അല്ലാഹുവിനേക്കാൾ സ്തുതികീർത്തനങ്ങൾ ഇഷ്ടപ്പെടുന്ന ആരുമില്ല. അതിനാലാണ് അല്ലാഹു സ്വയം സ്തുതിച്ചത് തന്നെ. മാത്രമല്ല, അല്ലാഹുവിനേക്കാൾ ദേഷ്യമുള്ള ഒരാളുമില്ല തന്നെ. അതിനാലാണ് എല്ലാ മോശമായ കാര്യങ്ങളും അവൻ നിഷിദ്ധമാക്കിയിരിക്കുന്നത്. അതുപോലെത്തന്നെ അല്ലാഹുവിനേക്കാൾ മാപ്പ്നൽകൽ ഇഷ്ടപ്പെടുന്ന ഒരാളുമില്ല. അതിനാലാണവൻ ഗ്രന്ഥം ഇറക്കുകയും ദൂതരെ അയക്കുകയും ചെയ്തത്." (മു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1011, 1011, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ يَغَارُ، وَإِنَّ الْمُؤْمِنَ يَغَارُ، وَغَيْرَةُ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ عَلَيْهِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ (സ) പറയുന്നു: "അല്ലാഹു ദേഷ്യപ്പെടും, സത്യവിശ്വാസിയും ദേഷ്യപ്പെടും, അല്ലാഹുവിന്റെ ദേഷ്യം ഒരു സത്യവിശ്വാസി, അവന്റെ മേൽ നിഷിദ്ധമാക്കപ്പെട്ടത് ചെയ്യുമ്പോഴാണ്."(മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1011, 1011, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ صَفْوَانَ بْنِ مُحْرِزٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَجُلٌ لِابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي النَّجْوَى؟ قَالَ: سَمِعْتُهُ يَقُولُ: "يُدْنَى الْمُؤْمِنُ يَوْمَ الْقِيَامَةِ مِنْ رَبِّهِ عَزَّ وَجَلَّ حَتَّى يَضَعَ عَلَيْهِ كَنَفَهُ، فَيُقَرِّرُهُ بِذُنُوبِهِ، فَيَقُولُ: هَلْ تَعْرِفُ؟ فَيَقُولُ: (أَيْ) رَبِّ أَعْرِفُ. قَالَ: فَإِنِّي قَدْ سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا، وَإِنِّي أَغْفِرُهَا لَكَ الْيَوْمَ. فَيُعْطَى صَحِيفَةَ حَسَنَاتِهِ. وَأَمَّا الْكُفَّارُ وَالْمُنَافِقُونَ. فَيُنَادَى بِهِمْ عَلَى رُءُوسِ الْخَلَائِقِ: هَؤُلَاءِ الَّذِينَ كَذَبُوا عَلَى اللَّهِ عز وَجَلَّ". (م)', 'സ്വാഫ്‌വാൻ ബിൻ മുഹ്‌രിസ്(റ): ഇബ്‌നുഉമർ(റ)വിനോട് ഒരാൾ ചോദിച്ചു: സ്വാകാര്യത്തെക്കുറിച്ച് റസൂൽ(സ) പറയുന്നതായി എന്താണ് താങ്കൾ കേട്ടിട്ടുള്ളത്? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "അന്ത്യനാളിൽ മുഅ്മിൻ തന്റെ രക്ഷിതാവുമായി അടുപ്പിക്കപ്പെടുകയും അവന്റെ മറയെ അവനിൽനിന്ന് നീക്കിവെക്കുകയും തന്റെ പാപങ്ങളെ അവനെക്കൊണ്ട് അംഗീകരിപ്പിക്കുകയും ചെയ്യും. എന്നിട്ട് ചോദിക്കും: ഇവയെന്തെന്ന് നീ അറിയുന്നുണ്ടോ? അവൻ പറയും. എന്റെ രക്ഷിതാവേ, ഞാൻ അറിയുന്നു. അല്ലാഹു പറയും. ദുനിയാവിൽ ഞാൻ നിനക്ക് ഇത് മറച്ചു വെച്ചു. ഇന്ന് ഞാൻ അത് നിനക്ക് പൊറുത്ത് തരുന്നു. ശേഷം അവന്റെ നന്മയുടെ ഏട് നൽകപ്പെടും. എന്നാൽ സത്യനിഷേധികളെക്കുറിച്ചും കപട വിശ്വാസികളെക്കുറിച്ചും സൃഷ്ടികൾക്കിടയിൽ വെച്ച് വിളിച്ച് പറയപ്പെടും: ഇവർ അല്ലാഹുവിനെ കളവാക്കിയവരാണ്." (മു)', 'صَفْوَانَ بْنِ مُحْرِزٍ', 'സ്വാഫ്‌വാൻ ബിൻ മുഹ്‌രിസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1012, 1012, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ، هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ قَالَ: "هَلْ تُضَارُّونَ فِي رُؤْيَةِ الشَّمْسِ فِي الظَّهِيرَةِ لَيْسَتْ فِي سَحَابَةٍ؟". قَالُوا: لَا. قَالَ: "فَهَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ فِي سَحَابَةٍ؟". قَالُوا: لَا، قَالَ: "فَوَالَّذِي نَفْسِي بِيَدِهِ لَا تُضَارُّونَ فِي رُؤْيَةِ رَبِّكُمْ إِلَّا كَمَا تُضَارُّونَ فِي رُؤْيَةِ أَحَدِهِمَا، قَالَ: فَيَلْقَى الْعَبْدَ فَيَقُولُ: أَيْ فُلْ! أَلَمْ أُكْرِمْكَ وَأُسَوِّدْكَ وَأُزَوِّجْكَ، وَأُسَخِّرْ لَكَ الْخَيْلَ وَالْإِبِلَ، وَأَذَرْكَ تَرْأَسُ وَتَرْبَعُ؟ فَيَقُولُ: بَلَى (أَيْ رَبِّ) قَالَ: فَيَقُولُ: أَفَظَنَنْتَ أَنَّكَ مُلَاقِيَّ؟ فَيَقُولُ: لَا. فَيَقُولُ: فَإِنِّي أَنْسَاكَ كَمَا نَسِيتَنِي. ثُمَّ يُلْقَى الثَّانِيَ فَيَقُولُ: أَيْ فُلْ! أَلَمْ أُكْرِمْكَ وَأُسَوِّدْكَ وَأُزَوِّجْكَ وَأُسَخِّرْ لَكَ الْخَيْلَ وَالْإِبِلَ، وَأَذَرْكَ تَرْأَسُ وَتَرْبَعُ؟ فَيَقُولُ: بَلَى أَيْ رَبِّ، فَيَقُولُ: أَفَظَنَنْتَ أَنَّكَ مُلَاقِيَّ؟ فَيَقُولُ: لَا، فَيَقُولُ: فَإِنِّي أَنْسَاكَ كَمَا نَسِيتَنِي، ثُمَّ يُلْقَى الثَّالِثَ فَيَقُولُ لَهُ مِثْلَ ذَلِكَ، فَيَقُولُ: يَا رَبِّ آمَنْتُ بِكَ وَبِكِتَابِكَ وَبِرُسُلِكَ، وَصَلَّيْتُ وَصُمْتُ وَتَصَدَّقْتُ، وَيُثْنِي بِخَيْرٍ مَا اسْتَطَاعَ، قَالَ: فَيَقُولُ: هَاهُنَا إِذًا. قَالَ: ثُمَّ يُقَالُ لَهُ: الْآنَ نَبْعَثُ شَاهِدَنَا عَلَيْكَ، وَيَتَفَكَّرُ فِي نَفْسِهِ: مَنْ ذَا الَّذِي يَشْهَدُ عَلَيَّ؟ فَيُخْتَمُ عَلَى فِيهِ، وَيُقَالُ لِفَخِذِهِ وَلَحْمِهِ وَعِظَامِهِ: انْطِقِي، فَتَنْطِقُ فَخِذُهُ وَلَحْمُهُ وَعِظَامُهُ بِعَمَلِهِ، وَذَلِكَ لِيُعْذِرَ مِنْ نَفْسِهِ، وَذَلِكَ الْمُنَافِقُ، وَذَلِكَ الَّذِي يَسْخَطُ اللَّهُ عَلَيْهِ". (م)', 'അബൂഹുറൈറ(റ): അവർ ചോദിച്ചു: തിരുദൂതരെ, അന്ത്യനാളിൽ ഞങ്ങൾ രക്ഷിതാവിനെ കാണുമോ? അവിടുന്ന് പറഞ്ഞു: "നട്ടുച്ചക്ക് മേഘങ്ങൾക്കിടയിലല്ലാത്ത സൂര്യനെ കാണാൻ നിങ്ങൾ ബുദ്ധിമുട്ടാറുണ്ടോ?"അവർ പറഞ്ഞു: ഇല്ല, അവിടുന്ന് ചോദിച്ചു: "പതിനാലാം രാവിലെ മേഖങ്ങൾക്കിടയിലല്ലാത്ത ചന്ദ്രനെ കാണാൻ നിങ്ങൾ ബുദ്ധിമുട്ടാറുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല, അവിടുന്ന് പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം നിങ്ങൾക്ക് ഇവ രണ്ടും കാണുന്നതിലുള്ള ബുദ്ധിമുട്ടേ നിങ്ങളുടെ രക്ഷിതാവിനെ കാണുന്നതിലും ഉണ്ടാകൂ." എന്നിട്ട് പറഞ്ഞു: "അവൻ തന്റെ ഒരടിമയെ കണ്ടുമുട്ടുമ്പോൾ ചോദിക്കും. ഓ, മനുഷ്യാ.. ഞാൻ നിന്നെ ബഹുമാനിച്ചില്ലയോ, നിന്നെ നേതാവാക്കിയില്ലെയോ, നിനക്ക് ഇണയെ തന്നില്ലെയോ?. നിനക്ക് കുതിരയെയും ഒട്ടകത്തെയും കീഴടക്കിത്തന്നില്ലെയോ? ശേഷം ക്ഷേമത്തോടെ ജീവിക്കുന്ന നേതാവാക്കി നിന്നെ ഞാൻ വിടുകയും ചെയ്തില്ലെയോ? അടിമ പറയും: അതെ, എന്റെ രക്ഷിതാവേ. അല്ലാഹു ചോദിക്കും: എന്നെ കണ്ടുമുട്ടുമെന്ന് നീ വിചാരിച്ചില്ലയോ? അവൻ പറയും: ഇല്ല, അല്ലാഹു പറയും: എങ്കിൽ നീ എന്നെ മറന്ന പോലെ ഞാൻ നിന്നെയും മറക്കുന്നു. ശേഷം അല്ലാഹു രണ്ടാമത്തവനെ കണ്ട് മുട്ടും. അല്ലാഹു ചോദിക്കും: ഓ, മനുഷ്യാ.. ഞാൻ നിന്നെ ബഹുമാനിക്കുകയും, നേതാവാക്കുകയും ഇണയെ തരികയും ഒട്ടകത്തെയും കുതിരയെയും കീഴടക്കിത്തിരികയും ശേഷം ക്ഷേമത്തോടെ ജീവിക്കുന്ന നേതാവാക്കി വിടുകയും ചെയ്തില്ലെയോ? അവൻ പറയും: അതെ, എന്റെ രക്ഷിതാവേ, അല്ലാഹു ചോദിക്കും: എന്നെ കണ്ടുമുട്ടുമെന്ന് അപ്പോൾ നീ വിചാരിച്ചില്ലെയോ? അവൻ പറയും: ഇല്ല. അപ്പോൾ അല്ലാഹു പറയും: എങ്കിൽ നീ എന്നെ മറന്നത് പോലെ ഞാൻ നിന്നെയും മറക്കുന്നു. ശേഷം മൂന്നാമത്തവനെ കാണുമ്പോൾ അത് പോലെ ചോദിക്കും: അപ്പോൾ അവൻ പറയും: എന്റെ രക്ഷിതാവേ, ഞാൻ നിന്നെ കൊണ്ട് വിശ്വസിച്ചു. നിന്റെ ഗ്രന്ഥം കൊണ്ടും, നിന്റെ ദൂതരെ കൊണ്ടും. ഞാൻ നമസ്കരിച്ചു, നോമ്പനുഷ്ഠിച്ചു, ദാനം ചെയ്തു. അങ്ങനെയവൻ അല്ലാഹുവിന് ധാരാളം സ്തുതികളർപ്പിക്കും. അപ്പോൾ അല്ലാഹു പറയും: മതി, നിങ്ങൾ നിർത്തുക. റസൂൽ(സ) പറയുന്നു: പിന്നെ അവനോട് പറയപ്പെടും: ഇന്നേരം നിന്നിലേക്ക് ഞാൻ നിനക്കെതിരെയുള്ള നമ്മുടെ സാക്ഷിയെ അയക്കുന്നു. അവൻ ചിന്തിച്ച് കൊണ്ടിരിക്കും. എനിക്കെതിരെ ആരാണ് സാക്ഷ്യം വഹിക്കുക. ഉടനെ അദ്ദേഹത്തിന്റെ വായ സീൽ വെക്കപ്പെടും. അവന്റെ തുടയോടും ഇറച്ചിയോടും എല്ലുകളോടും പറയപ്പെടും. നീ സംസാരിക്കുക. അപ്പോൾ അവന്റെ തുടയും ഇറച്ചിയും എല്ലുകളും അവന്റെ ചെയ്തികളെക്കുറിച്ച് പറയും. അത് തന്റെ ശരീരം തന്നെ കാരണം പറയാനാകുന്നു. അവൻ കപടവിശ്വാസിയാകുന്നു. അവനോടാണ് അല്ലാഹു ദേഷ്യപ്പെടുക." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1012, 1013, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَضَحِكَ، فَقَالَ: "هَلْ تَدْرُونَ مِمَّ أَضْحَكُ؟". قَالَ: قُلْنَا: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: مِنْ مُخَاطَبَةِ الْعَبْدِ رَبَّهُ، فَيَقُولُ: يَا رَبِّ أَلَمْ تُجِرْنِي مِنَ الظُّلْمِ؟ قَالَ: يَقُولُ: بَلَى. قَالَ: فَيَقُولُ: فَإِنِّي لَا أُجِيزُ عَلَى نَفْسِي إِلَّا شَاهِدًا مِنِّي. قَالَ: فَيَقُولُ: كَفَى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ شَهِيدًا، وَبِالْكِرَامِ الْكَاتِبِينَ شُهُودًا. قَالَ: فَيُخْتَمُ عَلَى فِيهِ، فَيُقَالُ لِأَرْكَانِهِ: انْطِقِي. قَالَ: فَتَنْطِقُ بِأَعْمَالِهِ. قَالَ: ثُمَّ يُخَلَّى بَيْنَهُ وَبَيْنَ الْكَلَامِ، قَالَ: فَيَقُولُ: بُعْدًا لَكُنَّ وَسُحْقًا، فَعَنْكُنَّ كُنْتُ أُنَاضِلُ". (م)', 'അനസുബ്നുമാലിക്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുത്തായിരുന്നപ്പോൾ അവിടുന്ന് ചിരിച്ചു. എന്നിട്ട് ചോദിച്ചു: "എന്തിനാണ് ഞാൻ ചിരിക്കുന്നതെന്ന് നിങ്ങൾക്കറിയുമോ?" ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് കൂടുതൽ അറിവുള്ളവർ. റസൂൽ(സ) പറഞ്ഞു: "അടിമ തന്റെ റബ്ബിനോട് നടത്തുന്ന സംഭാഷണമോർത്താണ് ഞാൻ ചിരിക്കുന്നത്. അടിമ ചോദിക്കും: എന്റെ നാഥാ, അക്രമങ്ങളിൽ നിന്നും നീ എന്നെ സംരക്ഷിച്ചില്ലെയോ? അല്ലാഹു പറയും: അതെ. അടിമ പറയും: ഇന്ന് ഞാനല്ലാതെ എനിക്ക് ഒരു സാക്ഷിയുമില്ല. അല്ലാഹു പറയും: നിനക്കെതിരിൽ സാക്ഷി നിൽക്കാൻ നിന്റെ തന്നെ ശരീരവും അതിനും സാക്ഷ്യം വഹിക്കാൻ നന്മതിന്മകളെഴുതുന്ന മാന്യന്മാരായ മലക്കുകളും മതി. ശേഷം ആ അടിമയുടെ വായയുടെ മേൽ സീല് വെക്കപ്പെടുകയും അവന്റെ അവയവങ്ങളോട് സംസാരിക്കാൻ കൽപ്പിക്കപ്പെടുകയും ചെയ്യും. അപ്പോൾ അവയവങ്ങൾ അവന്റെ കർമ്മങ്ങളെക്കുറിച്ച് പറയാൻ തുടങ്ങും. ശേഷം അവനെ സംസാരിക്കാൻ അനുവദിക്കും. അവൻ (അവയവങ്ങളോട്) പറയും: നിങ്ങൾക്കു നാശം, നിങ്ങൾക്ക് വേണ്ടിയായിരുന്നു ഞാൻ വാദിച്ചുകൊണ്ടിരുന്നത്. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1013, 1014, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَالَ رَجُلٌ لَمْ يَعْمَلْ حَسَنَةً قَطُّ لِأَهْلِهِ: إِذَا مَاتَ فَحَرِّقُوهُ، ثُمَّ اذْرُوا نِصْفَهُ فِي البَرِّ وَنِصْفَهُ فِي البَحْرِ، فَوَاللهِ لَئِنْ قَدَرَ اللهُ عَلَيْهِ لَيُعَذِّبَنَّهُ عَذَابًا لَا يُعَذِّبُهُ أَحَدًا مِنَ الْعَالَمِينَ. فَلَمَّا مَاتَ الرَّجُلُ فَعَلُوا مَا أَمَرَهُمْ، فَأَمَرَ اللهُ البَرَّ فَجَمَعَ مَا فِيهِ، وَأَمَرَ البَحْرَ فَجَمَعَ مَا فِيهِ، ثُمَّ قَالَ: لِمَ فَعَلْتَ هَذَا؟ قَالَ: مِنْ خَشْيَتِكَ يَا رَبِّ، وَأَنْتَ أَعْلَمُ. فَغَفَرَ اللهُ لَهُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "തീരെ നന്മ ചെയ്യാത്ത ഒരു വ്യക്തി തന്റെ കുടുംബക്കാരോട് പറഞ്ഞു: ഞാൻ മരിച്ചാൽ എന്നെ കരിച്ച് കളയുകയും അതിന്റെ പകുതി കടലിലും പകുതി കരയിലും ഇടുകയും ചെയ്യുക. കാരണം അല്ലാഹുവാണേ സത്യം, അല്ലാഹു അവനെ പിടികൂടിയാൽ ലോകത്ത് ആരെയും ശിക്ഷിക്കാത്ത ശിക്ഷ അവൻ നൽകും. അങ്ങനെ അദ്ദേഹം മരിച്ചപ്പോൾ അവർ അത് പോലെ ചെയ്തു. അപ്പോൾ അല്ലാഹു കരയോട്, അതിലുള്ള അയാളുടെ ഭാഗങ്ങളെ മുഴുവൻ ഒരുമിച്ചു കൂട്ടാൻ കൽപിക്കുകയും അത് ഒരുമിച്ച്കൂട്ടുകയും. പിന്നെ കടലിനോടും കൽപിച്ചു. അതിലുള്ളതിനെ കടലും ഒരുമിച്ചുകൂട്ടി. പിന്നെ അല്ലാഹു അവനോടു ചോദിച്ചു: നീ എന്തിനാണിങ്ങനെ ചെയ്തത്? അവൻ പറഞ്ഞു. നിന്നോടുള്ള പേടി കൊണ്ടാണ് എന്റെ രക്ഷിതാവേ, നീ ഏറ്റവും അറിയുന്നവനുമാണ്. അപ്പോൾ അല്ലാഹു അവന് പൊറുത്ത് കൊടുത്തു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1014, 1014, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - فِيمَا يَحْكِي عَنْ رَبِّهِ عَزَّ وَجَلَّ - قَالَ: "أَذْنَبَ عَبْدٌ ذَنْبًا فَقَالَ: اللَّهُمَّ اغْفِرْ لِي ذَنْبِي. فَقَالَ تَبَارَكَ وَتَعَالَى: أَذْنَبَ عَبْدِي ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ، ثُمَّ عَادَ فَأَذْنَبَ فَقَالَ: أَيْ رَبِّ اغْفِرْ لِي ذَنْبِي. فَقَالَ تَبَارَكَ وَتَعَالَى: عَبْدِي أَذْنَبَ ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِالذَّنْبِ. ثُمَّ عَادَ فَأَذْنَبَ، فَقَالَ: أَيْ رَبِّ، اغْفِرْ لِي ذَنْبِي. فَقَالَ تَبَارَكَ وَتَعَالَى: أَذْنَبَ عَبْدِي ذَنْبًا، فَعَلِمَ أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِالذَّنْبِ. اعْمَلْ مَا شِئْتَ فَقَدْ غَفَرْتُ لَكَ". قَالَ عَبْدُ الْأَعْلَى: لَا أَدْرِي أَقَالَ فِي الثَّالِثَةِ أَوْ الرَّابِعَةِ: "اعْمَلْ مَا شِئْتَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) അവിടുത്തെ രക്ഷിതാവിനെ ഉദ്ധരിച്ചുപറയുന്നതിൽ ഇങ്ങനെ പറയുന്നു: "ഒരു അടിമ ഒരു പാപം ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവേ, എന്റെ പാപത്തെ എനിക്ക് പൊറുത്ത് തരേണമേ. അപ്പോൾ അല്ലാഹു പറഞ്ഞു: എന്റെ അടിമ ഒരു പാപം ചെയ്തു. അങ്ങനെ അവൻ മനസ്സിലാക്കി, പാപങ്ങൾ പൊറുത്ത് കൊടുക്കുകയും പാപം കാരണം ശിക്ഷിക്കുകയും ചെയ്യുന്ന ഒരു രക്ഷിതാവ് അവനുണ്ടെന്ന്. പിന്നെ അവൻ വീണ്ടും തെറ്റ് ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവേ, എന്റെ പാപത്തെ എനിക്ക് പൊറുത്ത് തരേണമേ, അപ്പോൾ അല്ലാഹു പറഞ്ഞു: എന്റെ അടിമ ഒരു പാപം ചെയ്തു. അങ്ങനെ അവൻ മനസ്സിലാക്കി, പാപങ്ങൾ പൊറുത്ത് തരികയും പാപം കാരണം ശിക്ഷിക്കുകയും ചെയ്യുന്ന ഒരു രക്ഷിതാവ് അവനുണ്ടെന്ന്. ശേഷം വീണ്ടും അവൻ തെറ്റ് ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവേ, എന്റെ പാപം എനിക്ക് പൊറുത്ത് തരേണമേ. അപ്പോൾ അല്ലാഹു പറഞ്ഞു: എന്റെ അടിമ ഒരു പാപം ചെയ്തു. അങ്ങനെ അവൻ മനസ്സിലാക്കി പാപങ്ങൾ പൊറുത്ത് തരികയും പാപം കാരണം ശിക്ഷിക്കുകയും ചെയ്യുന്ന ഒരു രക്ഷിതാവ് അവനുണ്ടെന്ന്. നിനക്ക് തോന്നുന്നത് നീ ചെയ്യുക. ഞാൻ നിനക്ക് പൊറുത്ത് തന്നിരിക്കുന്നു." അബ്ദുൽ അഅ്‌ലാ പറയുന്നു: എനിക്കറിയില്ല. മൂന്നാമതാണോ അതോ നാലാമതാണോ ''നിനക്ക് തോന്നുന്നത് നീ ചെയ്യുക.'' എന്ന് പറഞ്ഞതെന്ന് എനിക്കറിയില്ല. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1014, 1015, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ وَنَحْنُ قُعُودٌ مَعَهُ، إِذْ جَاءَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ. فَسَكَتَ عَنْهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ أَعَادَ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ، فَسَكَتَ عَنْهُ، وَأُقِيمَتِ الصَّلَاةُ، فَلَمَّا انْصَرَفَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ أَبُو أُمَامَةَ : فَاتَّبَعَ الرَّجُلُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ انْصَرَفَ، وَاتَّبَعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْظُرُ مَا يَرُدُّ عَلَى الرَّجُلِ، فَلَحِقَ الرَّجُلُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ. قَالَ أَبُو أُمَامَةَ : فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرَأَيْتَ حِينَ خَرَجْتَ مِنْ بَيْتِكَ أَلَيْسَ قَدْ تَوَضَّأْتَ فَأَحْسَنْتَ الْوُضُوءَ". قَالَ: بَلَى يَا رَسُولَ اللهِ، قَالَ: "ثُمَّ شَهِدْتَ الصَّلَاةَ مَعَنَا". فَقَالَ: نَعَمْ يَا رَسُولَ اللهِ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَإِنَّ اللهَ قَدْ غَفَرَ لَكَ حَدَّكَ. أَوْ قَالَ: ذَنْبَكَ". (م)', 'അബു ഉമാമത്(റ): റസൂൽ(സ)യുടെ കൂടെ പള്ളിയിൽ ഞങ്ങൾ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ വന്നുപറഞ്ഞു: തിരുദൂതരേ, ഞാൻ ശിക്ഷക്കർഹനായിരിക്കുന്നു. അത് നടപ്പാക്കിയാലും. റസൂൽ(സ) അതിനെ കുറിച്ച് ഒന്നും പറഞ്ഞില്ല. വീണ്ടും പറഞ്ഞു: തിരുദൂതരെ, ഞാൻ ശിക്ഷക്കർഹനായിരിക്കുന്നു, അത് നടപ്പാക്കിയാലും. റസൂൽ(സ) ഒന്നും പറഞ്ഞില്ല. നിസ്കാരം നിർവ്വഹിക്കപ്പെട്ടു. നബി(സ) തിരിച്ച് പോന്നപ്പോൾ ആ മനുഷ്യൻ റസൂൽ(സ)യെ പിന്തുടർന്നു. എന്താണ് റസൂൽ(സ) അദ്ദേഹത്തോട് പറയുകയെന്ന് അറിയാൻ വേണ്ടി ഞാനും പിന്തുടർന്നു. അങ്ങനെ അദ്ദേഹം റസൂൽ(സ)യോട് ചെന്ന് പറഞ്ഞു: തിരുദൂതരെ, ഞാൻ ശിക്ഷക്കർഹനായിരിക്കുന്നു, അവിടുന്ന് നടപ്പാക്കിയാലും. അബൂഉമാമ(റ) പറയുന്നു: റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "താങ്കൾ വീട്ടിൽ നിന്ന് പുറപ്പെട്ടപ്പോൾ വുളു നന്നായി ചെയ്തിരുന്നില്ലേ." അദ്ദേഹം പറഞ്ഞു. അതെ, തിരുദൂതരെ. റസൂൽ(സ) ചോദിച്ചു: "ശേഷം ഞങ്ങളുടെ കൂടെ നിസ്കരിച്ചില്ലെയോ?" അദ്ദേഹം പറഞ്ഞു: അതെ, തിരുദൂതരെ. അപ്പോൾ അദ്ദേഹത്തോട് റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു നിന്റെ പാപങ്ങൾ/നിന്റെ ശിക്ഷ പൊറുത്ത് തന്നിരിക്കുന്നു." (മു)', 'أَبِي أُمَامَةَ', 'അബു ഉമാമത്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1015, 1015, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ يَوْمُ الْقِيَامَةِ دَفَعَ اللَّهُ عَزَّ وَجَلَّ إِلَى كُلِّ مُسْلِمٍ يَهُودِيًّا أَوْ نَصْرَانِيًّا، فَيَقُولُ: هَذَا فِكَاكُكَ مِنَ النَّارِ". (م)', 'അബുമുസ(റ): റസൂൽ(സ) പറയുന്നു: "അന്ത്യനാളിൽ അല്ലാഹു ഓരോ മുസ്‌ലിമിനും ഒരു ജൂതനെയോ നസ്‌റാനിയെയോ നൽകും. എന്നിട്ട് പറയും: ഇവൻ നരകത്തിൽ നിന്നുള്ള നിന്റെ മോചനമാകുന്നു." (മു)', 'أَبِي مُوسَى', 'അബുമുസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1016, 1016, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
